#include <file-io.h>

#include "tools/tools.h"
#include "new.h"
#include "version.h"

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

const char* CUTE_INI = "; cute package manager settings\n\
[cute]\n\
version = \"" VERSION "\"\n\
\n\
; your project settings\n\
[project]\n\
name = \"%s\"\n\
version = \"0.1.0\"\n\
type = \"%s\"\n\
\n\
; your project dependencies\n\
[dependencies]\n\
";

const char* CUTE_LOCK_INI = "; THIS FILE IS AUTO-GENERATED\n\
; DO NOT EDIT THIS FILE DIRECTLY\n\
";

const char* CMAKELISTS_TXT = "cmake_minimum_required(VERSION 3.10)\n\
\n\
project(%s C)\n\
\n\
set(CMAKE_C_STANDARD 11)\n\
set(CMAKE_C_STANDARD_REQUIRED ON)\n\
set(CMAKE_C_EXTENSIONS OFF)\n\
\n\
file(GLOB_RECURSE SRC\n\
	\"${CMAKE_CURRENT_SOURCE_DIR}/src/*.c\"\n\
)\n\
\n\
if(CMAKE_SOURCE_DIR STREQUAL CMAKE_CURRENT_SOURCE_DIR)\n\
	set(IS_ROOT_PROJECT TRUE)\n\
else()\n\
	set(IS_ROOT_PROJECT FALSE)\n\
endif()\n\
\n\
if(IS_ROOT_PROJECT)\n\
	file(GLOB installed_packages LIST_DIRECTORIES true\n\
		\"${CMAKE_CURRENT_SOURCE_DIR}/.libraries/*\"\n\
	)\n\
\n\
	set(PACKAGE_TARGETS \"\")\n\
\n\
	foreach(package_dir ${installed_packages})\n\
		if(IS_DIRECTORY \"${package_dir}\")\n\
			add_subdirectory(\"${package_dir}\")\n\
\n\
			get_filename_component(target_name \"${package_dir}\" NAME)\n\
			list(APPEND PACKAGE_TARGETS ${target_name})\n\
		endif()\n\
	endforeach()\n\
\n\
	if(EXISTS \"${CMAKE_CURRENT_SOURCE_DIR}/src/main.c\")\n\
		add_executable(${PROJECT_NAME} ${SRC})\n\
	else()\n\
		add_library(${PROJECT_NAME} STATIC ${SRC})\n\
	endif()\n\
\n\
	set(CUTE_TARGET ${PROJECT_NAME})\n\
\n\
	if(PACKAGE_TARGETS)\n\
		target_link_libraries(${CUTE_TARGET} PRIVATE ${PACKAGE_TARGETS})\n\
	endif()\n\
else()\n\
	get_filename_component(CUTE_TARGET \"${CMAKE_CURRENT_SOURCE_DIR}\" NAME)\n\
\n\
	add_library(${CUTE_TARGET} STATIC ${SRC})\n\
\n\
	target_include_directories(${CUTE_TARGET} PUBLIC\n\
		\"${CMAKE_CURRENT_SOURCE_DIR}/src\"\n\
	)\n\
endif()\n\
\n\
if(MSVC)\n\
	target_compile_options(${CUTE_TARGET} PRIVATE\n\
		/W4\n\
		/WX\n\
		$<$<CONFIG:Release>:/O2>\n\
		$<$<CONFIG:Debug>:/ZI;/Od>\n\
	)\n\
else()\n\
	target_compile_options(${CUTE_TARGET} PRIVATE\n\
		-Wall\n\
		-Werror\n\
		$<$<CONFIG:Release>:-O2>\n\
		$<$<CONFIG:Debug>:-g;-O0>\n\
	)\n\
endif()\n\
\n\
if(IS_ROOT_PROJECT)\n\
	INSTALL(TARGETS ${PROJECT_NAME}\n\
		RUNTIME DESTINATION bin\n\
	)\n\
endif()\n\
";

const char* MAIN_C = "#include <stdlib.h>\n\
#include <stdio.h>\n\
\n\
int main(int argc, char* argv[]) {\n\
	printf(\"Hello, world!\\n\");\n\
\n\
	return EXIT_SUCCESS;\n\
}\n\
";

const char* HEADER = "#ifndef %s_H\n\
#define %s_H\n\
\n\
\n\
#endif\n\
";

const char* GITIGNORE = "# Cute\n\
build/\n\
.libraries/\n\
";

new_project_result_t new_project(int argc, char* argv[]) {
	char* project_name = NULL;
	bool is_library = false;
	bool init = false;
	for (int i = 2; i < argc; i++) {
		if (argv[i][0] != '-') {
			if (project_name != NULL)
				return PROJECT_INVALID_ARGS;

			project_name = argv[i];
			continue;
		} else if (strcmp(argv[i], "--lib") == 0
				|| strcmp(argv[i], "-l") == 0) {
			is_library = true;
		} else if (strcmp(argv[i], "--init") == 0) {
			init = true;
		}
	}

	if (project_name == NULL)
		return PROJECT_NO_NAME;

	char* directory = init
		? format("./")
		: format("./%s", project_name);

	char* ini_path = format("%s/Cute.ini", directory);
	char* lock_path = format("%s/Cute.lock", directory);
	char* cmakelists_txt_path = format("%s/CMakeLists.txt", directory);
	char* gitignore_path = format("%s/.gitignore", directory);

	char* src_dir = format("%s/src", directory);
	char* main_path = is_library
		? format("%s/%s.c", src_dir, project_name)
		: format("%s/main.c", src_dir);

	char* libraries_dir = format("%s/.libraries", directory);

	if (!init) {
		if (directory_exists(project_name))
			return PROJECT_DIR_ALREADY_EXISTS;

		directory_create(project_name);
	}

	file_t ini_file = file_open(ini_path, WRITE_BINARY);
	fprintf(ini_file, CUTE_INI, project_name, is_library ? "library" : "executable");
	file_close(ini_file);

	file_t lock_file = file_open(lock_path, WRITE_BINARY);
	file_write(lock_file, CUTE_LOCK_INI, strlen(CUTE_LOCK_INI));
	file_close(lock_file);

	file_t cmakelists_txt_file = file_open(cmakelists_txt_path, WRITE_BINARY);
	fprintf(cmakelists_txt_file, CMAKELISTS_TXT, project_name);
	file_close(cmakelists_txt_file);

	// don't overwrite pre-existing .gitignores
	file_t gitignore_file = file_exists(gitignore_path)
		? file_open(gitignore_path, APPEND_BINARY)
		: file_open(gitignore_path, WRITE_BINARY);
	file_write(gitignore_file, GITIGNORE, strlen(GITIGNORE));
	file_close(gitignore_file);

	directory_create(src_dir);
	directory_create(libraries_dir);
	free(libraries_dir);

	if (!file_exists(main_path)) {
		file_t main_file = file_open(main_path, WRITE_BINARY);
		file_write(main_file, MAIN_C, strlen(MAIN_C));
		file_close(main_file);
	}

	if (is_library) {
		char* capitalised_project_name = bounded_strdup(project_name, 0, strlen(project_name));
		for (size_t i = 0; i < strlen(capitalised_project_name); i++) {
			capitalised_project_name[i] = (char)toupper((int)capitalised_project_name[i]);
		}

		char* header_path = format("%s/%s.h", src_dir, project_name);
		char* header_txt = format(HEADER, capitalised_project_name, capitalised_project_name);
		free(capitalised_project_name);

		if (!file_exists(header_path)) {
			file_t header_file = file_open(header_path, WRITE_BINARY);

			if (header_file != NULL)
				file_write(header_file, header_txt, strlen(HEADER));
			file_close(header_file);
		}

		free(header_path);
		free(header_txt);
	}

	free(directory);
	free(ini_path);
	free(lock_path);
	free(cmakelists_txt_path);
	free(src_dir);
	free(main_path);

	return PROJECT_SUCCESS;
}

